function freshTravel(){return {wood:0,shells:0,gathered:{},relations:{rabbit:0,bear:0,turtle:0},talkDays:{rabbit:0,bear:0,turtle:0},giftDays:{rabbit:0,bear:0,turtle:0},events:{rabbit:false,bear:false,turtle:false},garden:false,treasure:false}}
function validTravel(t,day){const keys=['rabbit','bear','turtle'];return t&&int(t.wood,0,999999)&&int(t.shells,0,999999)&&t.gathered&&typeof t.gathered==='object'&&!Array.isArray(t.gathered)&&Object.entries(t.gathered).length<=30&&Object.entries(t.gathered).every(([k,v])=>/^(log[0-7]|shell[0-5]|forestgift)$/.test(k)&&int(v,1,day))&&t.relations&&keys.every(k=>int(t.relations[k],0,100))&&t.talkDays&&keys.every(k=>int(t.talkDays[k],0,day))&&t.giftDays&&keys.every(k=>int(t.giftDays[k],0,day))&&t.events&&keys.every(k=>typeof t.events[k]==='boolean')&&typeof t.garden==='boolean'&&typeof t.treasure==='boolean'}
