function travelInteract(o){if(o.type==='exit'){goRegion(o.to);return true}if(o.type==='resident'){panel('resident:'+o.who);return true}if(['bridge','lighthouse','treasure','garden','bakery'].includes(o.type)){panel(o.type);return true}if(o.type==='fish'){beginFishing();return true}if(o.type==='gather'||o.type==='cat'){toast(travelAction(o.type,o.key));return true}return false}

let state=fresh(),storageOK=true;try{const raw=localStorage.getItem(KEY)||localStorage.getItem('lulu-homestead-study-v2');if(raw)state=migrate(JSON.parse(raw))}catch{storageOK=false;$('save-state').textContent='未能读取进度。可在存档面板重新导入备份。'}
