const beds=Array.from({length:24},(_,i)=>{const g=Math.floor(i/6),j=i%6;return {id:'plot'+i,type:'plot',i,x:930+(g>=2?570:0)+j%3*150,y:745+(g%2?275:0)+Math.floor(j/3)*125}});
