const decor=[...Array.from({length:6},(_,i)=>({frame:10,x:530+i*114,y:1090,w:122,h:79})),...[[480,545],[1420,697],[685,552],[1510,920],[1250,1010],[995,300],[385,1240]].map(([x,y])=>({frame:11,x,y,w:80,h:62})),...[[310,640],[1530,1050],[1900,1210],[920,1160]].map(([x,y])=>({frame:12,x,y,w:78,h:62}))];
