function passable(x,y){if(state.region!=='home'){if(x<25||x>2175||y<25||y>1475)return false;if(state.region==='pond'&&x>1255&&y>220&&y<1290)return false;if(state.region==='coast'&&x>1540)return false;return ![...regionalProps(),...regionalTrees()].some(o=>o.hit&&x+14>o.hit.x&&x-14<o.hit.x+o.hit.w&&y+7>o.hit.y&&y-7<o.hit.y+o.hit.h)}if(x<25||x>2175||y<25||y>1475)return false;return ![...props.map(o=>o.id==='house'?{...o,hit:{...o.hit,w:o.hit.w+state.house*40}}:o),...activeTrees()].some(o=>o.hit&&x+14>o.hit.x&&x-14<o.hit.x+o.hit.w&&y+7>o.hit.y&&y-7<o.hit.y+o.hit.h)}
