function paintWalkTarget(){if(!walkDestination)return;ctx.save();ctx.strokeStyle='#fff5c9';ctx.lineWidth=2.5;ctx.beginPath();ctx.ellipse(walkDestination.x,walkDestination.y,15,8,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#a47f45';ctx.beginPath();ctx.arc(walkDestination.x,walkDestination.y,3,0,Math.PI*2);ctx.fill();ctx.restore();}

const images={},imageJobs={};let ready=false,travelTicket=0,loadingRegion=null;
function loadArt(key){if(images[key]?.width>0)return Promise.resolve(images[key]);if(imageJobs[key])return imageJobs[key];imageJobs[key]=new Promise((resolve,reject)=>{const im=new Image();im.decoding='async';im.onload=async()=>{try{if(im.decode)await im.decode();images[key]=im;resolve(im)}catch(e){delete imageJobs[key];reject(e)}};im.onerror=()=>{delete imageJobs[key];reject(Error('图片加载失败'))};im.src=ASSETS[key]});return imageJobs[key]}
function regionArt(region){return region==='home'?'ground':region}
function loadingMessage(label,retry){const node=$('loading');node.hidden=false;node.textContent=label;if(retry){const b=document.createElement('button');b.textContent='重新加载';b.onclick=retry;node.appendChild(b)}}
function ensureRegionArt(){const key=regionArt(state.region);if(images[key]?.width>0)return true;if(loadingRegion===key)return false;loadingRegion=key;stopWalking();loadingMessage('正在打开'+REGION_NAMES[state.region]+'…');loadArt(key).then(()=>{loadingRegion=null;$('loading').hidden=true}).catch(()=>{loadingMessage('这张地图没能加载，请检查网络后重试。',()=>{loadingRegion=null;ensureRegionArt()})});return false}
function goRegion(name){if(!Object.hasOwn(REGION_NAMES,name)||!openRegion(name))return goRegionNow(name);const ticket=++travelTicket,key=regionArt(name);if(images[key]?.width>0)return goRegionNow(name);stopWalking();keys.clear();dismiss();loadingMessage('正在前往'+REGION_NAMES[name]+'…');loadArt(key).then(()=>{if(ticket!==travelTicket)return;$('loading').hidden=true;goRegionNow(name)}).catch(()=>{if(ticket===travelTicket)loadingMessage('地图加载失败，进度已保留。',()=>goRegion(name))})}
function bootGame(){loadingMessage('正在准备噜噜的小家…');const keys=['atlas','hero','crops','buildings','people','ground',regionArt(state.region)];Promise.all([...new Set(keys)].map(loadArt)).then(()=>{ready=true;$('loading').hidden=true;if(!state.prologueSeen)startOpening()}).catch(()=>loadingMessage('素材暂时没有加载成功，请检查网络后重试。',bootGame))}
bootGame();

function resize(){const r=canvas.getBoundingClientRect();vw=r.width;vh=r.height;zoom=vw<560?.72:.92;const d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(vw*d);canvas.height=Math.round(vh*d);ctx.setTransform(d,0,0,d,0,0)}window.addEventListener('resize',resize);resize();
function atlas(frame,x,y,w,h,alpha=1){const f=ATLAS[frame],scale=Math.min(w/f[2],h/f[3]),dw=f[2]*scale,dh=f[3]*scale;ctx.save();ctx.globalAlpha=alpha;ctx.drawImage(images.atlas,...f,x-dw/2,y-dh,dw,dh);ctx.restore()}
function extra(image,frames,frame,x,y,w,h){const f=frames[frame],z=Math.min(w/f[2],h/f[3]);ctx.drawImage(image,...f,x-f[2]*z/2,y-f[3]*z,f[2]*z,f[3]*z)}
function shadow(x,y,rx,ry,a=.16){ctx.fillStyle=`rgba(61,74,41,${a})`;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function hero(t){const row=facing==='north'?2:(facing==='east'||facing==='west')?1:0;const phase=Math.floor(t/180)%4;const index=row*3+(moving?(phase===1?1:phase===3?2:0):0);const f=HERO[index],h=83,w=h*f[2]/f[3];const bounce=bounceUntil>t?-Math.sin((bounceUntil-t)/400*Math.PI)*9:moving?0:Math.sin(t/650)*.7;shadow(state.x,state.y,23,8);ctx.save();ctx.translate(state.x,state.y+bounce);if(facing==='west')ctx.scale(-1,1);ctx.drawImage(images.hero,...f,-w/2,-h,w,h);ctx.restore()}
function paint(t){ctx.clearRect(0,0,vw,vh);if(!ready||!ensureRegionArt())return;const width=vw/zoom,height=vh/zoom;camX=Math.max(0,Math.min(WORLD.width-width,state.x-width/2));camY=Math.max(0,Math.min(WORLD.height-height,state.y-height*.59));ctx.save();ctx.scale(zoom,zoom);ctx.translate(-camX,-camY);if(state.region==='home')ctx.drawImage(images.ground,0,0,WORLD.width,WORLD.height);else ctx.drawImage(images[state.region],0,0,WORLD.width,WORLD.height);
if(state.region==='home')for(const b of beds.slice(0,state.plots.length)){const p=state.plots[b.i];atlas(p.wet||state.rain?5:4,b.x,b.y+40,151,93);if(p.crop&&p.growth===0&&!p.repeat){if(p.crop==='carrot')atlas(6,b.x,b.y+15,80,24);else extra(images.crops,CROPFRAMES,{berry:0,pumpkin:4,orange:8}[p.crop],b.x,b.y+15,45,30)}}
const layers=(state.region==='home'?[...props,...activeTrees(),...decor.filter(o=>o.frame!==10||!beds.slice(0,state.plots.length).some(b=>Math.abs(b.x-o.x)<95&&Math.abs(b.y-o.y)<80)),...beds.slice(0,state.plots.length).filter(b=>state.plots[b.i].crop&&(state.plots[b.i].growth>0||state.plots[b.i].repeat)).map(b=>({type:'crop',x:b.x,y:b.y+17,b}))]:[...regionalProps().filter(visibleRegional),...regionalTrees()]).concat([{type:'hero',x:state.x,y:state.y}],state.history.cat?[{type:'companion',actor:3,x:state.x-36,y:state.y+12,w:35,h:38}]:[]).sort((a,b)=>a.y-b.y);
for(const o of layers){if(o.x<camX-400||o.x>camX+width+400||o.y<camY-150||o.y>camY+height+400)continue;if(o.type==='hero'){hero(t);continue}if(o.actor!==undefined){if(o.type==='bridge'&&!state.history.bridge)ctx.globalAlpha=.5;extra(images.people,PEOPLEFRAMES,o.actor,o.x,o.y,o.w,o.h);ctx.globalAlpha=1;if(o.type==='lighthouse'&&state.history.lighthouse){ctx.save();ctx.globalAlpha=.15;ctx.fillStyle='#fff1ac';ctx.beginPath();ctx.moveTo(o.x,o.y-190);ctx.lineTo(o.x+330,o.y-260);ctx.lineTo(o.x+330,o.y-100);ctx.fill();ctx.restore()}continue}if(o.type==='crop'){const p=state.plots[o.b.i],stage=ripe(p)?3:p.repeat?2:p.growth===0?0:Math.min(2,Math.ceil(p.growth/daysFor(p)*2));if(p.crop==='carrot')atlas([6,7,8,9][stage],o.x,o.y,110,[24,37,63,75][stage]);else extra(images.crops,CROPFRAMES,{berry:0,pumpkin:4,orange:8}[p.crop]+stage,o.x,o.y,p.crop==='orange'?105:103,p.crop==='orange'?[25,45,100,125][stage]:[25,40,65,77][stage]);continue}if(o.building!==undefined){extra(images.buildings,BUILDINGFRAMES,o.building,o.x,o.y,o.w,o.h);continue}if(o.id==='house'&&state.house){extra(images.buildings,BUILDINGFRAMES,state.house,o.x+state.house*18,o.y,o.w+state.house*40,o.h+state.house*15);continue}if(o.type==='tree')shadow(o.x+5,o.y-3,54,17,.10);atlas(o.frame,o.x,o.y,o.w,o.h)}
if(state.region==='town'&&state.travel.garden){for(let i=0;i<6;i++)atlas(11,1000+(i%3)*90,470+Math.floor(i/3)*70,90,75)}if(state.region==='home')for(let i=0;i<state.decor;i++)atlas(11,595+i*90,555,75,60);const near=nearby();if(near){const x=near.x,y=near.y;ctx.strokeStyle='#fff4c3';ctx.lineWidth=2.4;ctx.setLineDash([5,5]);ctx.beginPath();ctx.ellipse(x,y+10,near.type==='plot'?68:38,near.type==='plot'?34:14,0,0,7);ctx.stroke();ctx.setLineDash([])}
paintWalkTarget();paintGoal();for(let i=particles.length-1;i>=0;i--){const p=particles[i],age=(t-p.t)/700;if(age>1){particles.splice(i,1);continue}ctx.globalAlpha=1-age;ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x+Math.cos(p.a)*age*35,p.y-12+Math.sin(p.a)*age*22-age*18,2.6,0,7);ctx.fill()}ctx.globalAlpha=1;ctx.restore();
if(state.rain){ctx.strokeStyle='#f2fbfa88';ctx.lineWidth=1;for(let i=0;i<35;i++){const x=(i*87+t*.03)%vw,y=(i*137+t*.23)%vh;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3,y+12);ctx.stroke()}}if(state.minute>1080){ctx.fillStyle=`rgba(35,46,76,${Math.min(.24,(state.minute-1080)/1000)})`;ctx.fillRect(0,0,vw,vh)}
mini.clearRect(0,0,220,150);if(state.region==='home')mini.drawImage(images.ground,0,0,220,150);else mini.drawImage(images[state.region],0,0,220,150);mini.fillStyle='#9c7957';if(state.region==='home')mini.fillRect(58,38,24,12);if(state.region==='home')for(const b of beds.slice(0,state.plots.length))mini.fillRect(b.x/10-5,b.y/10-3,10,6);mini.strokeStyle='#fff9e2';mini.lineWidth=1;mini.strokeRect(camX/10,camY/10,width/10,height/10);mini.fillStyle='#f49e43';mini.beginPath();mini.arc(state.x/10,state.y/10,3.2,0,7);mini.fill();
const names={home:'回家休息',well:'打水',shipping:'放入出货',shop:'买种子',guide:'看木牌',requests:'每日委托',exit:'前往路口',resident:'聊聊天',gather:'收集',bridge:'查看木桥',cat:'找到了！',fish:'钓鱼',lighthouse:'查看灯塔',garden:'恢复花园',treasure:'查看宝箱',bakery:'料理小铺'};$('use').textContent=near?(near.type==='plot'?{seed:'播种',water:'浇水',harvest:'收获'}[tool]:names[near.type]):'使用工具';$('context').textContent=near?.type==='plot'?`第 ${near.i+1} 块田 · ${!state.plots[near.i].crop?'空地':CROPS[state.plots[near.i].crop].name+' · '+(ripe(state.plots[near.i])?'成熟':state.plots[near.i].growth+'/'+daysFor(state.plots[near.i])+'天')}`:near?names[near.type]:'走近目标后使用';if(t>toastUntil&&$('toast').textContent)$('toast').textContent='';$('toast').hidden=!$('toast').textContent;
}
function frame(t){const dt=Math.min(.04,(t-previous)/1000);previous=t;moving=false;if(ready&&$('loading').hidden&&$('modal').hidden){let dx=Number(keys.has('right'))-Number(keys.has('left')),dy=Number(keys.has('down'))-Number(keys.has('up'));const len=Math.hypot(dx,dy);if(len){stopWalking();facing=dx?(dx<0?'west':'east'):(dy<0?'north':'south');const x=state.x,y=state.y;dx=dx/len*170*dt;dy=dy/len*170*dt;if(passable(state.x+dx,state.y))state.x+=dx;if(passable(state.x,state.y+dy))state.y+=dy;moving=x!==state.x||y!==state.y}else advanceWalk(dt)}if(moving&&t-lastSaved>1600){save();lastSaved=t}paint(t);requestAnimationFrame(frame)}hud();if(!storageOK)$('save-state').textContent='自动保存不可用，请在「存档」中导出备份。';requestAnimationFrame(frame);

/* 橘子岛午后 — original 16-bar miniature, 80 BPM, softly synthesized offline. */
(()=>{
const button=document.getElementById('music-toggle'),volume=document.getElementById('music-volume');
const PREF='lulu-island-music-v1';let enabled=true,level=.3;
try{const p=JSON.parse(localStorage.getItem(PREF)||'null');if(p){enabled=p.enabled!==false;if(Number.isFinite(p.volume))level=Math.max(0,Math.min(.7,p.volume))}}catch{}
volume.value=String(Math.round(level*100));let context,master,bus,timer=null,unlocked=false,step=0,next=0,inFlight=false;
const voices=new Set(),beat=60/80;
const chords=[[48,52,55,59],[45,48,52,55],[41,45,48,52],[43,47,50,57],[48,52,55,59],[45,48,52,55],[41,45,48,52],[43,47,50,55],[48,52,55,59],[45,48,52,55],[41,45,48,52],[43,47,50,57],[41,45,48,52],[43,47,50,55],[48,52,55,59],[48,52,55,59]];
const tune=[[76,null,79,76,74,null,72,null],[72,null,76,79,76,null,69,null],[69,null,72,76,74,72,69,null],[71,null,74,79,77,null,74,null],[76,79,81,null,79,76,74,null],[72,null,76,79,81,null,79,76],[77,null,76,72,69,null,72,null],[74,null,71,67,72,null,null,null],[79,null,76,79,84,null,81,79],[81,null,79,76,72,null,69,null],[77,null,76,72,76,null,77,null],[79,null,77,74,71,null,74,null],[77,null,76,72,69,null,72,76],[74,null,71,67,71,null,74,null],[76,null,79,76,72,null,74,null],[72,null,null,null,null,null,null,null]];
function save(){try{localStorage.setItem(PREF,JSON.stringify({enabled,volume:level}))}catch{}}
function label(){button.textContent=!enabled?'♫ 音乐：关':context?.state==='running'?'♫ 音乐：开':'♫ 音乐：待播放';button.setAttribute('aria-pressed',String(enabled));button.title='橘子岛午后 · 点击切换背景音乐'}
function create(){const AC=window.AudioContext||window.webkitAudioContext;if(!AC){button.textContent='音乐暂不可用';button.disabled=true;return false}context=new AC();master=context.createGain();master.gain.value=level;const filter=context.createBiquadFilter();filter.type='lowpass';filter.frequency.value=2600;const compressor=context.createDynamicsCompressor();compressor.threshold.value=-18;compressor.ratio.value=3;bus=context.createGain();bus.gain.value=.6;bus.connect(filter);filter.connect(compressor);compressor.connect(master);master.connect(context.destination);const echo=context.createDelay(1);echo.delayTime.value=beat*.75;const wet=context.createGain();wet.gain.value=.13;filter.connect(echo);echo.connect(wet);wet.connect(master);context.onstatechange=label;return true}
function note(midi,time,duration,amplitude,type='sine',pad=false){const o=context.createOscillator(),g=context.createGain();o.type=type;o.frequency.value=440*Math.pow(2,(midi-69)/12);const start=.0001;g.gain.setValueAtTime(start,time);g.gain.exponentialRampToValueAtTime(amplitude,time+(pad?.65:.018));g.gain.exponentialRampToValueAtTime(start,time+duration);o.connect(g);g.connect(bus);o.start(time);o.stop(time+duration+.03);voices.add(o);o.onended=()=>{voices.delete(o);o.disconnect();g.disconnect()}}
function schedule(){if(context.state!=='running'||!enabled||document.hidden)return;if(next<context.currentTime-.2)next=context.currentTime+.08;while(next<context.currentTime+.18){const bar=Math.floor(step/8)%16,k=step%8,c=chords[bar],m=tune[bar][k];if(k===0){for(const n of c)note(n+12,next,beat*4.8,.018,'sine',true);note(c[0]-12,next,beat*2.6,.055,'sine')}if(k===4)note(c[2]-12,next,beat*1.8,.03);const arpeggio=c[[0,2,1,3,0,2,1,2][k]]+12;note(arpeggio,next,beat*.75,.021,'triangle');if(m!==null){note(m,next,beat*1.65,.054);note(m+12,next,.18,.007)}step=(step+1)%128;next+=beat/2}}
function stop(){if(timer!==null){clearInterval(timer);timer=null}for(const o of voices){try{o.stop()}catch{}}voices.clear();if(context&&context.state==='running')context.suspend().catch(()=>{});label()}
async function start(){if(!enabled||document.hidden||inFlight)return;if(!context&&!create())return;inFlight=true;try{await context.resume();unlocked=true;if(enabled&&!document.hidden&&context.state==='running'){if(timer===null){next=context.currentTime+.08;schedule();timer=setInterval(schedule,60)}}else stop()}catch{button.title='轻点音乐按钮开始播放'}finally{inFlight=false;label()}}
function gesture(e){if(e.target.closest?.('.music-controls'))return;if(enabled)start()}
document.addEventListener('pointerdown',gesture,{passive:true});document.addEventListener('keydown',gesture);
button.addEventListener('click',()=>{if(enabled&&!unlocked){start();return}enabled=!enabled;save();if(enabled)start();else stop();label()});volume.addEventListener('input',()=>{level=Number(volume.value)/100;if(master)master.gain.setTargetAtTime(level,context.currentTime,.08);save()});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();else if(unlocked&&enabled)start()});window.addEventListener('pagehide',stop);window.addEventListener('blur',stop);window.addEventListener('focus',()=>{if(unlocked&&enabled)start()});label();
})();
